// Deterministic rule-based scorer used when the Python ranking service is unavailable.
//
// Same formulas as ranking-service/app/scoring.py for every signal EXCEPT `text`
// (TF-IDF similarity, which needs the Python model). Missing `text` is handled the same
// way the service handles a user with no description: the weight is dropped and the rest
// re-normalised. tests/fallbackScorer.test.js checks this file against
// ranking-service/tests/fixtures/parity.json, which is generated by the Python code.

export const WEIGHTS = { text: 0.35, investment: 0.25, benefit: 0.15, specificity: 0.15, age: 0.10 };
export const TIER_FACTOR = { eligible: 1.0, possibly_eligible: 0.9 };

const clip01 = (x) => Math.max(0, Math.min(1, x));

const fmtInr = (x) => {
  if (x >= 1e7) return `₹${(x / 1e7).toFixed(1)} Cr`;
  if (x >= 1e5) return `₹${(x / 1e5).toFixed(1)}L`;
  return `₹${Math.round(x).toLocaleString('en-IN')}`;
};

const num = (v) => {
  if (v === null || v === undefined || typeof v === 'boolean') return null;
  if (typeof v === 'string' && v.trim() === '') return null;
  const f = Number(v);
  return Number.isFinite(f) ? f : null;
};

const slug = (v) => (typeof v === 'string' && v.trim() !== '' ? v.trim().toLowerCase().replace(/[ -]/g, '_') : null);
const slugs = (v) => {
  if (v && typeof v === 'object' && !Array.isArray(v)) v = Object.keys(v);
  return Array.isArray(v) ? v.map(slug).filter(Boolean) : [];
};
const titleCase = (s) => s.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());

function investmentFit(investment, rules, maxInvestment) {
  const inv = num(investment);
  let limit = num(rules.max_project_cost);
  if (limit === null || limit <= 0) limit = num(maxInvestment);
  if (inv === null || limit === null || limit <= 0) return [null, null];
  const lo = num(rules.min_project_cost) || 0;
  const target = lo > 0 ? Math.sqrt(lo * limit) : limit;
  const fit = 1 - Math.min(1, Math.abs(Math.log10(Math.max(inv, 1)) - Math.log10(target)) / 2);
  const reason = fit >= 0.7
    ? `Your investment (${fmtInr(inv)}) is close to this scheme's typical size (${fmtInr(target)})`
    : null;
  return [fit, reason];
}

function benefitMagnitude(benefits) {
  const b = benefits || {};
  const pct = num(b.subsidy_percent);
  const maxSub = num(b.max_subsidy);
  const loan = num(b.loan_amount);
  const pctC = pct !== null ? clip01(pct / 100) : 0;
  let amt = 0;
  if (maxSub !== null && maxSub > 0) amt = clip01(Math.log10(maxSub) / 7);
  else if (loan !== null && loan > 0) amt = clip01(Math.log10(loan) / 8) * 0.5;
  const value = 0.6 * pctC + 0.4 * amt;
  let reason = null;
  if (value >= 0.5) {
    const bits = [];
    if (pct !== null) bits.push(`${pct}% subsidy`);
    if (maxSub !== null) bits.push(`up to ${fmtInr(maxSub)}`);
    reason = 'Strong financial benefit' + (bits.length ? ` (${bits.join(', ')})` : '');
  }
  return [value, reason];
}

function userGroups(profile) {
  const g = new Set();
  const gender = slug(profile.gender);
  const social = slug(profile.social_category);
  const special = slug(profile.special_category);
  if (gender === 'female') g.add('women');
  if (gender === 'transgender') g.add('transgender');
  if (social === 'sc' || social === 'st') { g.add(social); g.add('sc_st'); }
  if (social === 'obc') g.add('obc');
  if (special) {
    g.add(special);
    if (special === 'bpl_women' || special === 'widow') g.add('women');
  }
  return g;
}

function specificity(profile, scheme, rules) {
  let score = 0;
  const reasons = [];

  const userLoc = slug(profile.location);
  const states = slugs(rules.states).filter((s) => s !== 'all_india' && s !== 'any');
  let schemeLoc = slug(scheme.location);
  if (schemeLoc === null || schemeLoc === 'any' || schemeLoc === 'all_india') schemeLoc = null;
  if (userLoc && (states.includes(userLoc) || schemeLoc === userLoc)) {
    score += 0.4;
    reasons.push(`Specific to ${titleCase(userLoc)}`);
  }

  const userCat = slug(profile.business_category);
  const own = slug(scheme.business_category);
  let cats = slugs(rules.business_categories);
  if (cats.length === 0 && own) cats = [own];
  if (cats.length && !cats.includes('any') && userCat && userCat !== 'any' && cats.includes(userCat)) {
    score += 0.3;
    reasons.push(`Targets ${userCat} businesses`);
  }

  const targets = new Set([...slugs(scheme.beneficiary_categories), ...slugs(rules.special_categories), ...slugs(rules.social_categories)]);
  const genders = slugs(rules.genders);
  if (genders.length === 1 && genders[0] === 'female') targets.add('women');
  const mine = userGroups(profile);
  const hit = [...targets].filter((t) => mine.has(t)).sort();
  if (hit.length) {
    score += 0.3;
    reasons.push('Priority scheme for ' + hit.map((h) => (h === 'sc_st' ? 'SC/ST' : h.replace(/_/g, ' '))).join(', '));
  }
  return [Math.min(1, score), reasons];
}

function ageFit(age, rules) {
  const a = num(age);
  const hi = num(rules.max_age);
  if (a === null || hi === null) return [null, null];
  const lo = num(rules.min_age) || 18;
  if (hi <= lo) return [null, null];
  const centre = (lo + hi) / 2;
  const half = (hi - lo) / 2;
  const fit = clip01(1 - Math.abs(a - centre) / half);
  const reason = fit >= 0.8 ? `Your age (${a}) is well within this scheme's target range (${lo}-${hi})` : null;
  return [fit, reason];
}

export function combine(components, tier) {
  const keys = Object.keys(components).filter((k) => components[k] !== null && components[k] !== undefined);
  const totalW = keys.reduce((s, k) => s + WEIGHTS[k], 0);
  if (totalW === 0) return 0;
  const base = keys.reduce((s, k) => s + WEIGHTS[k] * components[k], 0) / totalW;
  return clip01(base * (TIER_FACTOR[tier] ?? 1));
}

// profile: normalised profile (engine.normalizeProfile). scheme: payload shape sent to the
// service ({ rules (canonical), benefits, location, business_category, beneficiary_categories, max_investment, tier }).
export function scoreScheme(profile, scheme) {
  const rules = scheme.rules || {};
  const comps = { text: null };
  const notes = {};

  [comps.investment, notes.investment] = investmentFit(profile.investment, rules, scheme.max_investment);
  [comps.benefit, notes.benefit] = benefitMagnitude(scheme.benefits);
  [comps.specificity, notes.specificity] = specificity(profile, scheme, rules);
  [comps.age, notes.age] = ageFit(profile.age, rules);

  const score = Math.round(combine(comps, scheme.tier || 'eligible') * 1e6) / 1e6;

  const lines = (k) => (Array.isArray(notes[k]) ? notes[k] : notes[k] ? [notes[k]] : []);
  const ordered = Object.keys(notes)
    .filter((k) => lines(k).length)
    .sort((a, b) => WEIGHTS[b] * (comps[b] || 0) - WEIGHTS[a] * (comps[a] || 0) || (a < b ? -1 : 1));
  let reasons = ordered.flatMap(lines).slice(0, 4);
  if (reasons.length === 0) reasons = ['Meets the eligibility rules for this scheme'];
  return { score, reasons };
}
